import React from 'react';

function CheckoutPage() {
  return (
    <div>
      <h1>Checkout</h1>
      <form>
        <div>
          <label>Name:</label>
          <input type="text" required />
        </div>
        <div>
          <label>Address:</label>
          <input type="text" required />
        </div>
        <button type="submit">Place Order</button>
      </form>
    </div>
  );
}

export default CheckoutPage;
